function IS_SELF_DUAL(C, n):
  S <- set(C)
  for each x in {0,1}^n:
    orth <- TRUE
    for c in C:
      if <x,c> mod 2 != 0: orth <- FALSE; break
    if (x in S) != orth: return FALSE
  return TRUE

function DIRECT_SUM(C, D):
  out <- empty list
  for a in C:
    for b in D:
      append the concatenation a||b to out
  return out

function GLEASON_DIVISOR(C, n):
  lhs <- sum over c in C of i^{weight(c)}
  rhs <- (1+i)^n
  assert lhs == rhs and |C| == rhs        # master identity
  assert n mod 8 == 0                       # period-8 of (1+i)
  return 8
